export const SHOPS=[
{id:'coffee',name:'Cà phê',english:'Coffee house',code:'CF',size:3,color:'#825d43'},
{id:'banhmi',name:'Bánh mì',english:'Sandwich shop',code:'BM',size:3,color:'#b7782c'},
{id:'pho',name:'Phở',english:'Noodle kitchen',code:'PH',size:4,color:'#b85539'},
{id:'flowers',name:'Tiệm hoa',english:'Flower shop',code:'HO',size:4,color:'#a16586'},
{id:'tailor',name:'Tiệm may',english:'Tailor',code:'MA',size:5,color:'#587c9a'},
{id:'grocery',name:'Tạp hóa',english:'Corner grocer',code:'TH',size:6,color:'#648454'}];
export const DISTRICTS=['Tân Định','Bến Thành','Thảo Điền','Chợ Lớn','Bình Thạnh','Phú Nhuận'];
export const COLORS=['#39a883','#eec353','#dc6f57','#7fb5cf'];
export const KEEP=[5,4,3,2,2,2];
export const COMPLETE=[0,0,0,50,80,110,140];
export const INCOMPLETE=[0,10,20,40,60,80];
export function shuffle(a,rng=Math.random){return a.map(x=>[rng(),x]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);}
export function neighbors(id){const b=Math.floor(id/12),i=id%12,x=i%4,y=Math.floor(i/4);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([x,y])=>x>=0&&x<4&&y>=0&&y<3).map(([x,y])=>b*12+y*4+x);}
export function groups(state,player){const seen=new Set(),out=[];for(const lot of state.lots){if(lot.owner!==player||lot.shop===null||seen.has(lot.id))continue;const stack=[lot.id],ids=[];seen.add(lot.id);while(stack.length){const id=stack.pop();ids.push(id);for(const n of neighbors(id)){const next=state.lots[n];if(next.owner===player&&next.shop===lot.shop&&!seen.has(n)){seen.add(n);stack.push(n);}}}out.push({shop:lot.shop,lots:ids,size:ids.length});}return out;}
export function groupIncome(shop,count){const target=SHOPS[shop].size;return Math.floor(count/target)*COMPLETE[target]+INCOMPLETE[count%target];}
export function income(state,player){return groups(state,player).reduce((n,g)=>n+groupIncome(g.shop,g.size),0);}
export function holdings(state,player){return state.lots.filter(x=>x.owner===player);}
export function newGame(rng=Math.random){const state={version:1,year:1,phase:'receive',players:['You','Linh','Minh','An'].map((name,id)=>({id,name,cash:50,tiles:[0,0,0,0,0,0]})),lots:Array.from({length:72},(_,id)=>({id,owner:null,shop:null})),bag:shuffle(Array.from({length:120},(_,i)=>i%6),rng),pending:[],draftCount:0,logs:[],lastIncome:[],trades:0};startYear(state,rng);return state;}
function drawTiles(state,player,count){for(let i=0;i<count&&state.bag.length;i++)state.players[player].tiles[state.bag.pop()]++;}
function plotScore(state,id,player){return neighbors(id).reduce((n,k)=>n+(state.lots[k].owner===player?3:state.lots[k].owner===null?1:0),0);}
function botDraft(state,player,count,rng){const offered=shuffle(state.lots.filter(l=>l.owner===null&&!state.pending.includes(l.id)).map(l=>l.id),rng).slice(0,count+2);for(let i=0;i<count&&offered.length;i++){offered.sort((a,b)=>plotScore(state,b,player)-plotScore(state,a,player));state.lots[offered.shift()].owner=player;}}
export function startYear(state,rng=Math.random){state.phase='receive';state.lastIncome=[];const count=KEEP[state.year-1];state.draftCount=count;state.pending=shuffle(state.lots.filter(l=>l.owner===null).map(l=>l.id),rng).slice(0,count+2);for(let p=0;p<4;p++)drawTiles(state,p,state.year===1?5:4);log(state,`Year ${state.year}: new addresses and ${state.year===1?5:4} shop tiles arrived.`);}
export function claimPlots(state,ids,rng=Math.random){if(state.phase!=='receive')throw Error('You can choose addresses only at the start of a year.');if(!Array.isArray(ids)||ids.length!==state.draftCount||new Set(ids).size!==ids.length||ids.some(id=>!state.pending.includes(id)||state.lots[id].owner!==null))throw Error(`Choose exactly ${state.draftCount} of your offered plots.`);for(const id of ids)state.lots[id].owner=0;state.pending=[];for(let p=1;p<4;p++)botDraft(state,p,state.draftCount,rng);state.phase='trade';log(state,`You claimed plots ${ids.map(i=>i+1).join(', ')}.`);return ids;}
export function beginBuild(state){if(state.phase!=='trade')throw Error('Finish choosing your plots first.');state.phase='build';log(state,'Trading closed. Time to open your shops.');}
export function canPlace(state,player,id,shop){if(!Number.isInteger(id)||!state.lots[id]||!Number.isInteger(shop)||!SHOPS[shop])return false;const lot=state.lots[id];if(lot.owner!==player||lot.shop!==null||state.players[player].tiles[shop]<1)return false;return true;}
export function placeShop(state,id,shop,player=0){if(state.phase!=='build')throw Error('Shops open during the Build phase.');if(!canPlace(state,player,id,shop))throw Error('Choose your own empty plot and a tile you have in hand.');state.lots[id].shop=shop;state.players[player].tiles[shop]--;log(state,`${state.players[player].name} opened ${SHOPS[shop].name} on plot ${id+1}.`);return {id,shop};}
export function botBuild(state,player){let guard=0;while(guard++<30){let best=null;for(const l of holdings(state,player).filter(l=>l.shop===null)){for(let s=0;s<SHOPS.length;s++){if(!canPlace(state,player,l.id,s))continue;const adjacent=neighbors(l.id).filter(n=>state.lots[n].owner===player&&state.lots[n].shop===s).length;const possible=neighbors(l.id).filter(n=>state.lots[n].owner===player&&state.lots[n].shop===null).length;const before=income(state,player);l.shop=s;const delta=income(state,player)-before;l.shop=null;const score=delta*2+adjacent*8+possible*2+state.players[player].tiles[s]-SHOPS[s].size;if(!best||score>best.score)best={id:l.id,shop:s,score};}}if(!best)break;placeShop(state,best.id,best.shop,player);}}
export function finishYear(state){if(state.phase!=='build')throw Error('Finish trading before collecting income.');for(let p=1;p<4;p++)botBuild(state,p);state.lastIncome=state.players.map(p=>income(state,p.id));for(let p=0;p<4;p++)state.players[p].cash+=state.lastIncome[p];log(state,`Year ${state.year} closed. You earned ${state.lastIncome[0]} đ.`);state.phase=state.year===6?'ended':'income';return state.lastIncome;}
export function nextYear(state,rng=Math.random){if(state.phase!=='income')throw Error('Collect this year’s income first.');state.year++;startYear(state,rng);}
export function log(state,message){state.logs.unshift(message);if(state.logs.length>100)state.logs.length=100;}
const sideValue=(state,side,recipient)=>side.cash+side.tiles.reduce((v,count,i)=>v+count*(10+state.players[recipient].tiles[i]*1.5+groups(state,recipient).filter(g=>g.shop===i&&g.size<SHOPS[i].size).length*6),0)+side.lots.reduce((v,id)=>{const l=state.lots[id];const adjacency=neighbors(id).filter(n=>state.lots[n].owner===recipient).length;return v+18+adjacency*14+(l.shop===null?0:15+10*(7-state.year));},0);
export function emptyOffer(){return {cash:0,tiles:[0,0,0,0,0,0],lots:[]};}
export function validateOffer(state,offer){if(state.phase!=='trade')throw Error('Deals are available only during the Trade phase.');if(!offer||!Number.isInteger(offer.partner)||offer.partner<1||offer.partner>3)throw Error('Choose a trading partner.');for(const [side,player] of [[offer.give,0],[offer.take,offer.partner]]){if(!side||!Number.isInteger(side.cash)||side.cash<0||side.cash>state.players[player].cash)throw Error('Cash must be a whole number within the owner’s balance.');if(!Array.isArray(side.tiles)||side.tiles.length!==6||side.tiles.some((n,i)=>!Number.isInteger(n)||n<0||n>state.players[player].tiles[i]))throw Error('A player cannot trade more shop tiles than they hold.');if(!Array.isArray(side.lots)||new Set(side.lots).size!==side.lots.length||side.lots.some(id=>!Number.isInteger(id)||!state.lots[id]||state.lots[id].owner!==player))throw Error('Each plot can be offered once by its current owner.');}if(![offer.give,offer.take].some(s=>s.cash||s.lots.length||s.tiles.some(Boolean)))throw Error('Add cash, a shop tile, or a plot to the deal.');return true;}
export function evaluateOffer(state,offer){validateOffer(state,offer);const offered=sideValue(state,offer.give,offer.partner),requested=sideValue(state,offer.take,offer.partner);const margin=[0,1.04,1.09,1.01][offer.partner];return {accepted:offered>=requested*margin,shortfall:Math.max(0,Math.ceil(requested*margin-offered))};}
export function trade(state,offer){const result=evaluateOffer(state,offer);if(!result.accepted)return result;const a=state.players[0],b=state.players[offer.partner];a.cash+=offer.take.cash-offer.give.cash;b.cash+=offer.give.cash-offer.take.cash;for(let i=0;i<6;i++){a.tiles[i]+=offer.take.tiles[i]-offer.give.tiles[i];b.tiles[i]+=offer.give.tiles[i]-offer.take.tiles[i];}for(const id of offer.give.lots)state.lots[id].owner=offer.partner;for(const id of offer.take.lots)state.lots[id].owner=0;state.trades++;log(state,`Deal ${state.trades}: you and ${b.name} traded ${offer.give.lots.length+offer.take.lots.length} plots, ${offer.give.tiles.reduce((a,b)=>a+b,0)+offer.take.tiles.reduce((a,b)=>a+b,0)} tiles and cash.`);return result;}
export function rankings(state){return [...state.players].sort((a,b)=>b.cash-a.cash||state.lots.filter(l=>l.owner===b.id&&l.shop!==null).length-state.lots.filter(l=>l.owner===a.id&&l.shop!==null).length);}
export function validSave(s){return s&&s.version===1&&Number.isInteger(s.year)&&s.year>=1&&s.year<=6&&['receive','trade','build','income','ended'].includes(s.phase)&&Array.isArray(s.players)&&s.players.length===4&&s.players.every((p,i)=>p.id===i&&typeof p.name==='string'&&p.name.length>0&&Number.isFinite(p.cash)&&p.cash>=0&&Array.isArray(p.tiles)&&p.tiles.length===6&&p.tiles.every(n=>Number.isInteger(n)&&n>=0))&&Array.isArray(s.lots)&&s.lots.length===72&&s.lots.every((l,i)=>l.id===i&&(l.owner===null||Number.isInteger(l.owner)&&l.owner>=0&&l.owner<4)&&(l.shop===null||Number.isInteger(l.shop)&&l.shop>=0&&l.shop<6))&&Array.isArray(s.bag)&&s.bag.every(n=>Number.isInteger(n)&&n>=0&&n<6)&&Array.isArray(s.pending)&&s.pending.every(n=>Number.isInteger(n)&&n>=0&&n<72)&&Array.isArray(s.logs)&&s.logs.every(x=>typeof x==='string')&&Array.isArray(s.lastIncome)&&s.lastIncome.every(n=>Number.isFinite(n)&&n>=0)&&Number.isInteger(s.draftCount)&&s.draftCount>=2&&s.draftCount<=5;}
